INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 1, 0.0, 24, 1, "リン", "2020/04/30 12:00:00", "あたしだって\nやるときはやるよ！", 0, 24001);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 1, 0.0, 24, 1, "リン", "2020/04/30 12:00:00", "ふぅ…\nこれであたしの仕事は\n終わりだね", 1, 24002);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 1, 0.0, 24, 1, "リン", "2020/04/30 12:00:00", "終わった終わった\n一人でもなんとか\nなるもんだね", 2, 24003);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 2, 0.0, 24, 2, "リン", "2020/04/30 12:00:00", "やったね！\nこれでようやく\nサボれるよ…", 3, 24004);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 1, 0.0, 24, 1, "リン", "2020/04/30 12:00:00", "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 4, 24005);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 2, 0.0, 24, 2, "リン", "2020/04/30 12:00:00", "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 5, 24006);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 2, 0.0, 24, 2, "リン", "2020/04/30 12:00:00", "あたしも意外と\nやるもんでしょ？", 6, 24007);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 4, 0.0, 24, 4, "リン", "2020/04/30 12:00:00", "疲れた…\nねずみの逃げ足\n速すぎるよ…", 7, 24008);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 4, 0.0, 24, 4, "リン", "2020/04/30 12:00:00", "このままじゃ\nまっひ～に\n叱られちゃうよ", 8, 24009);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 4, 0.0, 24, 4, "リン", "2020/04/30 12:00:00", "まじめに\nやったんだけどな…\n悔しいな～", 9, 24010);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 4, 0.0, 24, 4, "リン", "2020/04/30 12:00:00", "やられた…\nねずみって意外と\nてごわいね", 10, 24011);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 0.0, 10040, 102601, 0.0, 4, 0.0, 24, 4, "リン", "2020/04/30 12:00:00", "おのれ～\nあたしのチーズを\n盗みやがって～！", 11, 24012);
INSERT INTO `v1_c39e9dcfaa50cc56d82d7c70d1e929b68b5e6d04691dc4e0316e35a7d42f94ff` VALUES ("2030/12/17 14:59:59", 1.81, 10040, 102601, 0.0, 1, 0.0, 24, 4, "リン", "2020/04/30 12:00:00", "疲れた…\nけど、次こそは\n守り抜くよ…", 12, 24013);
